def transform(grid):
    """Color each 2x2 tile: full squares are 1; three-cell L tiles encode their missing corner."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    # Mapping inferred from demos; color 5 is the remaining L orientation.
    missing_to_color = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 5}
    for r in range(h - 1):
        for c in range(w - 1):
            coords = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            present = [(rr, cc) for rr, cc in coords if grid[rr][cc] == 8]
            if len(present) == 4:
                color = 1
            elif len(present) == 3:
                missing = next((rr, cc) for rr, cc in coords if grid[rr][cc] != 8)
                color = missing_to_color[(missing[0] - r, missing[1] - c)]
            else:
                continue
            for rr, cc in present:
                out[rr][cc] = color
    return out
