def transform(grid):
    """Tile 8-cells with 2x2 squares and L triominoes; color by motif orientation."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    candidates = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            candidates.append((square, 1))
            for missing, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)]:
                candidates.append((square - {missing}, color))
    candidates = [(shape, color) for shape, color in candidates if shape <= cells]
    by_cell = {cell: [] for cell in cells}
    for shape, color in candidates:
        for cell in shape:
            by_cell[cell].append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = cover(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    tiling = cover(cells)
    if tiling is None:
        raise ValueError("Input 8-cells cannot be tiled by the learned motifs")
    out = [[0] * w for _ in range(h)]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
